  border-radius: 8px;
  overflow: hidden;
  transition: all 0.2s ease;
}

.example:hover {
  border-color: #4a5568;
  box-shadow: 0 4px 12px rgba(96, 165, 250, 0.1);
}

.example h3 {
  margin: 0;
  padding: 0;
}

.example button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 20px;
  background: transparent;
  border: none;
  color: #e0e0e0;
  font-size: 1.1rem;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: all 0.2s ease;
  gap: 16px;
}

.example button:hover {
  background: rgba(96, 165, 250, 0.05);
  color: #60a5fa;
}

.example button:focus {
  outline: 2px solid #60a5fa;
  outline-offset: -2px;
  background: rgba(96, 165, 250, 0.08);
}

/* Focus visible for keyboard navigation */
.example button:focus-visible {
  outline: 2px solid #60a5fa;
  outline-offset: -2px;
}

.example button::after {
  content: '';
  display: inline-block;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  background: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>') no-repeat center;
  background-size: contain;
  transition: transform 0.2s ease;
}

.example button[aria-expanded="true"]::after {
  transform: rotate(180deg);
}

.details {
  padding: 0 20px;
  max-height: 0;
  overflow: hidden;
  transition: all 0.3s ease;
  opacity: 0;
}

.details[hidden] {
  display: none;
}

.example button[aria-expanded="true"] ~ .details {
  padding: 0 20px 20px 20px;
  max-height: 1000px;
  opacity: 1;
}

.details p {
  color: #c0c0d0;
  font-size: 1rem;
  margin-bottom: 0;
}

/* Responsive design */
@media (max-width: 640px) {
  .faq-header h1 {
    font-size: 2rem;
  }

  .faq-header {
    margin-bottom: 30px;
    padding-bottom: 20px;
  }

  main {
    padding: 20px 16px;
  }

  .example button {
    padding: 16px;
    font-size: 1rem;
  }

  .details {
    padding: 0 16px;
  }

  .example button[aria-expanded="true"] ~ .details {
    padding: 0 16px 16px 16px;
  }
}

/* Forced Colors support */
@media (forced-colors: active) {
  .example {
    border: 1px solid;
