  // Initialize all disclosure widgets
  document.querySelectorAll('[aria-expanded]').forEach((btn) => {
    const panel = btn.closest('h2').nextElementSibling;

    // Collapse panels on init — content stays visible without JS
    btn.setAttribute('aria-expanded', 'false');
    panel.hidden = true;

    // Toggle panel on button click
    btn.addEventListener('click', () => {
      const isOpen = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', String(!isOpen));
      panel.hidden = isOpen;
    });

    // Optional: Allow Escape to close an open panel
    btn.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && btn.getAttribute('aria-expanded') === 'true') {
        btn.setAttribute('aria-expanded', 'false');
        panel.hidden = true;
        btn.focus();
      }
    });
  });
});
